package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.apache.kafka.clients.consumer.*;import io.knowledgebrain.contracts.planning.recurrence.v1.*;import io.knowledgebrain.contracts.planning.schedule.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP",matches=".+")
class RecurrenceKafkaIntegrationTest {
 @Test void atomicSeriesAndIndependentChildEventsReachScopedKafkaAsExactBytes()throws Exception{var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var store=new RecurrenceStore(ds,Clock.systemUTC());var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();String trace="e".repeat(32),key=UUID.randomUUID().toString().replace("-","");var input=new RecurrenceRules.Input("Kafka recurrence","Original","2028-11-04T09:00:00","2028-11-04T10:00:00","America/New_York",null,"DAILY",1,3,"REJECT","REJECT");var plan=store.preview(space,input);var original=store.create(space,actor,key,input,plan.previewHash(),trace).recurrence();var cancellation=store.cancellation(space,original.recurrenceId(),2);store.cancel(space,original.recurrenceId(),actor,1,2,cancellation.cancellationHash(),trace);assertEquals(original,store.create(space,ids.next(),key,input,plan.previewHash(),trace).recurrence());var aggregates=new HashSet<String>();aggregates.add(original.recurrenceId().toString());original.occurrences().forEach(v->aggregates.add(v.scheduleId().toString()));var expected=new HashMap<String,byte[]>();var args=new ArrayList<Object>();args.add(original.recurrenceId());original.occurrences().forEach(v->args.add(v.scheduleId()));new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid IN (?,?,?,?)",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),args.toArray()).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(7,expected.size());
var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP"));p.put("group.id","planning-validation-"+ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.ByteArrayDeserializer");p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/planning-kafka-test/ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/planning-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/planning-kafka-test/user.key")));

  try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("planning.recurrence.v1","planning.schedule.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<7&&System.nanoTime()<deadline)for(var row:c.poll(Duration.ofSeconds(1))){if(!aggregates.contains(row.key()))continue;var e=RecurrenceEventEnvelopeV1.parseFrom(row.value());assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals("planning-service",e.getProducer());assertEquals(space.toString(),e.getSpaceId());assertEquals(actor.toString(),e.getActorId());assertEquals(trace,e.getTraceId());assertEquals(1,e.getEventVersion());String artifact;if(row.topic().equals("planning.recurrence.v1")){artifact="recurrence-events";var v=RecurrenceChangedPayloadV1.parseFrom(e.getPayload());assertEquals("Recurrence",e.getAggregateType());assertEquals(3,v.getOccurrencesCount());assertEquals(plan.previewHash(),v.getPreviewHash());assertEquals(v.getVersion()==1?"RecurrenceCreated":"RecurrenceRetired",e.getEventType());assertEquals(v.getVersion()==1?0:2,v.getRetiredFromOrdinal());for(int n=0;n<3;n++){var pin=original.occurrences().get(n);var actual=v.getOccurrences(n);assertEquals(pin.scheduleId().toString(),actual.getScheduleId());assertEquals(pin.startsAt(),actual.getStartsAt());assertEquals(pin.startsOffset(),actual.getStartsOffset());}if(!found.contains(e.getEventId()))versions.add(v.getVersion());}else{artifact="schedule-events";var v=ScheduleChangedPayloadV1.parseFrom(e.getPayload());assertEquals("Schedule",e.getAggregateType());assertEquals(v.getVersion()==1?"ScheduleCreated":"ScheduleRetired",e.getEventType());assertTrue(original.occurrences().stream().anyMatch(pin->pin.scheduleId().toString().equals(v.getScheduleId())&&pin.startsAt().equals(v.getStartsAt())&&pin.startsOffset().equals(v.getStartsOffset())));}for(var h:Map.of("id",e.getEventId(),"trace_id",trace,"schema_group","planning","schema_artifact",artifact,"schema_version","1").entrySet())assertEquals(h.getValue(),new String(row.headers().lastHeader(h.getKey()).value(),StandardCharsets.UTF_8));found.add(e.getEventId());}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L),versions);}
 }
}
